import {aiEnabled,requestAI} from './personalization.js';
async function assist(kind,extra={}){return requestAI('assist',{kind,...extra});}
window.explainQuiz=async(id,container)=>{let output=container.querySelector('.quiz-more');if(!output){output=document.createElement('p');output.className='quiz-more';container.append(output);}if(!aiEnabled()){output.textContent='AI 해설이 꺼져 있습니다. 출처 링크에서 원문을 확인할 수 있습니다.';return;}output.textContent='해설 확인 중…';try{const result=await assist('quiz',{questionId:id});output.textContent=result.text+(result.mode==='fallback'?' · 검증된 기본 해설':'');}catch(error){output.textContent=error.message;}};
const wishForm=document.querySelector('#wish-form'),recommend=document.createElement('button');recommend.type='button';recommend.textContent='장식 추천';recommend.disabled=!aiEnabled();window.addEventListener('lab:preferences',()=>{recommend.disabled=!aiEnabled();});const notice=document.createElement('small');notice.className='ai-notice';notice.textContent='설정 → 소리에서 AI 추천을 켤 수 있습니다. 추천을 누르면 소원 내용이 OpenAI로 전송됩니다.';const recommendation=document.createElement('div');recommendation.className='wish-recommendation';recommendation.append(recommend,notice);wishForm.querySelector('.wish-decoration-options').append(recommendation);recommend.onclick=async()=>{const output=wishForm.querySelector('output[role=status]'),text=wishForm.elements.message.value.trim();if(!text){output.textContent='소원을 먼저 입력해 주세요.';return;}recommend.disabled=true;try{const result=await assist('wish',{text});output.textContent=result.text+(result.mode==='fallback'?' · 기본 추천':'');window.dispatchEvent(new CustomEvent('lab:decoration-choice',{detail:result}));}catch(error){output.textContent=error.message;}finally{recommend.disabled=!aiEnabled();}};
